import * as React from 'react';
import {cva,type VariantProps} from 'class-variance-authority';
import {motion} from 'motion/react';
import {Dialog as D} from '@base-ui/react/dialog';
import {Tabs as T} from '@base-ui/react/tabs';
import {Switch as S} from '@base-ui/react/switch';
import {Checkbox as C} from '@base-ui/react/checkbox';
import {Select as Se} from '@base-ui/react/select';
import {Menu as M} from '@base-ui/react/menu';
import {Popover as P} from '@base-ui/react/popover';
import {Tooltip as Tip} from '@base-ui/react/tooltip';
import {Accordion as A} from '@base-ui/react/accordion';
import {Slider as Sl} from '@base-ui/react/slider';
import {Check,ChevronDown,Plus,X,Loader2} from 'lucide-react';
import {cn} from '../../lib/nbrain-utils';

const buttonVariants=cva('nb-button',{variants:{variant:{primary:'button-primary',silver:'button-silver',secondary:'button-secondary',ghost:'button-ghost',outline:'button-outline',destructive:'button-destructive'},size:{sm:'button-sm',md:'button-md',lg:'button-lg',icon:'button-icon'}},defaultVariants:{variant:'secondary',size:'md'}});
export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement>,VariantProps<typeof buttonVariants>{loading?:boolean}
export const Button=React.forwardRef<HTMLButtonElement,ButtonProps>(({variant,size,className,children,loading,disabled,...props},ref)=><button ref={ref} className={cn(buttonVariants({variant,size}),className)} disabled={disabled||loading} aria-busy={loading||undefined} {...props}>{loading&&<Loader2 className="spin" size={16}/>} {children}</button>);
Button.displayName='Button';
export const Input=React.forwardRef<HTMLInputElement,React.InputHTMLAttributes<HTMLInputElement>>(({className,...p},r)=><input className={cn('nb-input',className)} ref={r} {...p}/>);Input.displayName='Input';
export const Textarea=React.forwardRef<HTMLTextAreaElement,React.TextareaHTMLAttributes<HTMLTextAreaElement>>(({className,...p},r)=><textarea className={cn('nb-input nb-textarea',className)} ref={r} {...p}/>);Textarea.displayName='Textarea';
export function Field({label,hint,error,children,id}: {label:string;hint?:string;error?:string;children:React.ReactElement;id?:string}){const auto=React.useId();const key=id||auto;return <div className="nb-field"><label htmlFor={key}>{label}</label>{React.cloneElement(children,{id:key,'aria-invalid':!!error,'aria-describedby':hint||error?key+'-hint':undefined})}{(hint||error)&&<span id={key+'-hint'} className={error?'field-error':'field-hint'}>{error||hint}</span>}</div>}
export function Badge({children,tone='neutral',className}:{children:React.ReactNode;tone?:'neutral'|'blue'|'success'|'warning'|'danger';className?:string}){return <span className={cn('nb-badge','badge-'+tone,className)}>{children}</span>}
export function Card({children,className,glass=false,...p}:React.HTMLAttributes<HTMLDivElement>&{glass?:boolean}){return <div {...p} className={cn('nb-card',glass&&'nb-glass',className)}>{children}</div>}
export function Separator(){return <div className="nb-separator" role="separator"/>}
export function Skeleton({className}: {className?:string}){return <div aria-hidden="true" className={cn('nb-skeleton',className)}/>}
export function Progress({value,label='Progress'}:{value:number;label?:string}){return <div className="nb-progress" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={value} aria-label={label}><motion.div initial={false} animate={{width:`${Math.max(0,Math.min(100,value))}%`}} transition={{duration:.4}}/></div>}
export function Avatar({initials='JD',size='md',status=false}:{initials?:string;size?:'sm'|'md'|'lg';status?:boolean}){return <span className={cn('nb-avatar','avatar-'+size)} aria-label={initials}>{initials}{status&&<i/>}</span>}
export function AvatarGroup({people}:{people:string[]}){return <div className="avatar-group">{people.map(p=><Avatar initials={p} key={p}/>)}</div>}
export function Switch({label,checked,onCheckedChange,disabled}: {label:string;checked:boolean;onCheckedChange:(v:boolean)=>void;disabled?:boolean}){return <label className="check-label"><S.Root className="nb-switch" checked={checked} onCheckedChange={onCheckedChange} disabled={disabled} aria-label={label}><S.Thumb className="switch-thumb"/></S.Root><span>{label}</span></label>}
export function Checkbox({label,checked,onCheckedChange,disabled}: {label:string;checked:boolean;onCheckedChange:(v:boolean)=>void;disabled?:boolean}){return <label className="check-label"><C.Root className="nb-checkbox" checked={checked} onCheckedChange={onCheckedChange} disabled={disabled} aria-label={label}><C.Indicator><Check size={13}/></C.Indicator></C.Root>{label}</label>}
export function Slider({value,onValueChange,label,min=0,max=100}: {value:number;onValueChange:(v:number)=>void;label:string;min?:number;max?:number}){return <Sl.Root className="nb-slider" value={value} onValueChange={v=>onValueChange(Array.isArray(v)?v[0]:v)} min={min} max={max}><div className="slider-label"><Sl.Label>{label}</Sl.Label><span className="mono">{value}</span></div><Sl.Control className="slider-control"><Sl.Track className="slider-track"><Sl.Indicator className="slider-indicator"/><Sl.Thumb className="slider-thumb"/></Sl.Track></Sl.Control></Sl.Root>}
export function Select({value,onValueChange,options,label}:{value:string;onValueChange:(v:string)=>void;options:{value:string;label:string}[];label:string}){return <Se.Root value={value} onValueChange={v=>v&&onValueChange(v)} items={options}><Se.Trigger className="nb-select" aria-label={label}><Se.Value/><Se.Icon><ChevronDown size={14}/></Se.Icon></Se.Trigger><Se.Portal><Se.Positioner sideOffset={6} className="popup-positioner"><Se.Popup className="nb-popup"><Se.List>{options.map(o=><Se.Item className="nb-menu-item" key={o.value} value={o.value}><Se.ItemText>{o.label}</Se.ItemText><Se.ItemIndicator><Check size={14}/></Se.ItemIndicator></Se.Item>)}</Se.List></Se.Popup></Se.Positioner></Se.Portal></Se.Root>}
export function Tabs({items,value,onValueChange}:{items:{value:string;label:string;content:React.ReactNode}[];value:string;onValueChange:(v:string)=>void}){return <T.Root value={value} onValueChange={v=>onValueChange(String(v))}><T.List className="nb-tabs">{items.map(i=><T.Tab className="nb-tab" key={i.value} value={i.value}>{i.label}</T.Tab>)}<T.Indicator className="tab-indicator"/></T.List>{items.map(i=><T.Panel className="tab-panel" key={i.value} value={i.value}>{i.content}</T.Panel>)}</T.Root>}
export function Dialog({open,onOpenChange,title,description,children,sheet=false}:{open:boolean;onOpenChange:(v:boolean)=>void;title:string;description?:string;children:React.ReactNode;sheet?:boolean}){return <D.Root open={open} onOpenChange={onOpenChange}><D.Portal><D.Backdrop className="nb-backdrop"/><D.Popup className={cn('nb-dialog nb-glass',sheet&&'nb-sheet')}><div className="dialog-heading"><D.Title>{title}</D.Title><D.Close className="nb-button button-icon button-ghost" aria-label="Close"><X size={18}/></D.Close></div>{description&&<D.Description className="muted">{description}</D.Description>}<div className="dialog-content">{children}</div></D.Popup></D.Portal></D.Root>}
export function DropdownMenu({label,items}:{label:React.ReactNode;items:{label:string;onClick:()=>void;danger?:boolean}[]}){return <M.Root><M.Trigger className="nb-button button-secondary button-md">{label}<ChevronDown size={14}/></M.Trigger><M.Portal><M.Positioner sideOffset={6} className="popup-positioner"><M.Popup className="nb-popup">{items.map(i=><M.Item key={i.label} className={cn('nb-menu-item',i.danger&&'danger-text')} onClick={i.onClick}>{i.label}</M.Item>)}</M.Popup></M.Positioner></M.Portal></M.Root>}
export function Popover({trigger,children,label}:{trigger:React.ReactNode;children:React.ReactNode;label:string}){return <P.Root><P.Trigger className="nb-button button-secondary button-md" aria-label={label}>{trigger}</P.Trigger><P.Portal><P.Positioner sideOffset={8} className="popup-positioner"><P.Popup className="nb-popup popover-content">{children}</P.Popup></P.Positioner></P.Portal></P.Root>}
export function Tooltip({children,text}:{children:React.ReactElement;text:string}){return <Tip.Root><Tip.Trigger render={children}/><Tip.Portal><Tip.Positioner sideOffset={8} className="popup-positioner"><Tip.Popup className="nb-tooltip">{text}</Tip.Popup></Tip.Positioner></Tip.Portal></Tip.Root>}
export const TooltipProvider=Tip.Provider;
export function Accordion({items}:{items:{title:string;content:React.ReactNode}[]}){return <A.Root className="nb-accordion">{items.map((item,i)=><A.Item key={i} value={i}><A.Header><A.Trigger className="accordion-trigger">{item.title}<Plus size={16}/></A.Trigger></A.Header><A.Panel className="accordion-panel">{item.content}</A.Panel></A.Item>)}</A.Root>}
export function Alert({title,children,tone='blue'}:{title:string;children?:React.ReactNode;tone?:'blue'|'warning'|'danger'|'success'}){return <div role={tone==='danger'?'alert':'status'} className={cn('nb-alert','alert-'+tone)}><strong>{title}</strong>{children&&<p>{children}</p>}</div>}
export function Empty({icon,title,description,action}:{icon:React.ReactNode;title:string;description:string;action?:React.ReactNode}){return <div className="nb-empty"><div className="empty-icon">{icon}</div><h4>{title}</h4><p className="muted">{description}</p>{action}</div>}
export function Kbd({children}:{children:React.ReactNode}){return <kbd className="nb-kbd">{children}</kbd>}
export function ToggleGroup({items,value,onChange,label}:{items:{value:string;label:React.ReactNode}[];value:string;onChange:(v:string)=>void;label:string}){return <div className="nb-toggle-group" role="group" aria-label={label}>{items.map(i=><button key={i.value} aria-pressed={value===i.value} onClick={()=>onChange(i.value)} className={value===i.value?'selected':''}>{i.label}</button>)}</div>}
export function Breadcrumb({items}:{items:string[]}){return <nav aria-label="Breadcrumb" className="nb-breadcrumb">{items.map((i,n)=><React.Fragment key={i}>{n>0&&<span>/</span>}<span aria-current={n===items.length-1?'page':undefined}>{i}</span></React.Fragment>)}</nav>}
export function Pagination({page,pages,onChange}:{page:number;pages:number;onChange:(v:number)=>void}){return <nav aria-label="Pagination" className="row"><Button size="sm" disabled={page===1} onClick={()=>onChange(page-1)}>Previous</Button>{Array.from({length:pages},(_,i)=><Button key={i} size="sm" variant={page===i+1?'primary':'ghost'} aria-current={page===i+1?'page':undefined} onClick={()=>onChange(i+1)}>{i+1}</Button>)}<Button size="sm" disabled={page===pages} onClick={()=>onChange(page+1)}>Next</Button></nav>}

import * as React from 'react';
import {Combobox as C} from '@base-ui/react/combobox';
import {Collapsible as Co} from '@base-ui/react/collapsible';
import {ContextMenu as CM} from '@base-ui/react/context-menu';
import {NumberField as NF} from '@base-ui/react/number-field';
import {ChevronLeft,ChevronRight,ChevronDown,Check,Minus,Plus,Upload,Search} from 'lucide-react';
import {Button,Input,Popover,Empty} from './primitives';
export function Combobox({items,value,onChange,label}:{items:string[];value:string;onChange:(v:string)=>void;label:string}){return <C.Root items={items} value={value} onValueChange={v=>v&&onChange(v)}><C.InputGroup className="combo-group"><C.Input className="nb-input" aria-label={label}/><C.Trigger className="combo-trigger" aria-label={'Open '+label}><ChevronDown size={15}/></C.Trigger></C.InputGroup><C.Portal><C.Positioner className="popup-positioner" sideOffset={6}><C.Popup className="nb-popup"><C.Empty className="combo-empty">No results.</C.Empty><C.List>{(item:string)=><C.Item key={item} value={item} className="nb-menu-item">{item}<C.ItemIndicator><Check size={14}/></C.ItemIndicator></C.Item>}</C.List></C.Popup></C.Positioner></C.Portal></C.Root>}
export function NumberInput({value,onChange,label,min=0,max=100}:{value:number;onChange:(v:number)=>void;label:string;min?:number;max?:number}){return <NF.Root value={value} onValueChange={v=>onChange(v??min)} min={min} max={max} className="nb-number"><NF.Group><NF.Decrement aria-label={'Decrease '+label}><Minus size={14}/></NF.Decrement><NF.Input aria-label={label}/><NF.Increment aria-label={'Increase '+label}><Plus size={14}/></NF.Increment></NF.Group></NF.Root>}
export function Collapsible({title,children}:{title:string;children:React.ReactNode}){return <Co.Root><Co.Trigger className="collapsible-trigger">{title}<ChevronDown size={14}/></Co.Trigger><Co.Panel className="collapsible-panel">{children}</Co.Panel></Co.Root>}
export function ContextMenu({children,items}:{children:React.ReactNode;items:{label:string;onClick:()=>void}[]}){return <CM.Root><CM.Trigger className="context-target">{children}</CM.Trigger><CM.Portal><CM.Positioner className="popup-positioner"><CM.Popup className="nb-popup">{items.map(i=><CM.Item key={i.label} className="nb-menu-item" onClick={i.onClick}>{i.label}</CM.Item>)}</CM.Popup></CM.Positioner></CM.Portal></CM.Root>}
export function Calendar({value,onChange}:{value:string;onChange:(v:string)=>void}){const [view,setView]=React.useState(()=>new Date(value+'T12:00:00'));const year=view.getFullYear(),month=view.getMonth(),days=new Date(year,month+1,0).getDate(),offset=(new Date(year,month,1).getDay()+6)%7;return <div className="nb-calendar"><div className="row between"><Button size="icon" variant="ghost" aria-label="Previous month" onClick={()=>setView(new Date(year,month-1,1))}><ChevronLeft size={16}/></Button><strong>{view.toLocaleDateString('en',{month:'long',year:'numeric'})}</strong><Button size="icon" variant="ghost" aria-label="Next month" onClick={()=>setView(new Date(year,month+1,1))}><ChevronRight size={16}/></Button></div><div className="calendar-grid">{['Mo','Tu','We','Th','Fr','Sa','Su'].map(d=><span key={d}>{d}</span>)}{Array.from({length:offset},(_,i)=><i key={'blank'+i}/>)}{Array.from({length:days},(_,i)=>{const v=`${year}-${String(month+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return <button key={v} className={v===value?'selected':''} aria-pressed={v===value} aria-label={v} onClick={()=>onChange(v)}>{i+1}</button>})}</div></div>}
export function DatePicker({value,onChange,label}:{value:string;onChange:(v:string)=>void;label:string}){return <Popover label={label} trigger={<>{value}<ChevronDown size={14}/></>}><Calendar value={value} onChange={onChange}/></Popover>}
export function RadioGroup({value,onChange,options,label}:{value:string;onChange:(v:string)=>void;options:{value:string;label:string}[];label:string}){const id=React.useId();return <fieldset className="radio-field"><legend>{label}</legend>{options.map(o=><label key={o.value} className="check-label"><input type="radio" name={id} checked={value===o.value} onChange={()=>onChange(o.value)}/>{o.label}</label>)}</fieldset>}
export function FileUpload({accept,onFile,label='Attach a script'}:{accept?:string;onFile:(file:File)=>void;label?:string}){const [name,setName]=React.useState('');return <label className="upload-zone"><Upload size={20}/><strong>{name||label}</strong><span className="muted small">Choose a file</span><input type="file" aria-label={label} accept={accept} onChange={e=>{const f=e.target.files?.[0];if(f){setName(f.name);onFile(f)}}}/></label>}
export function ScrollArea({children,height=180}:{children:React.ReactNode;height?:number}){return <div tabIndex={0} className="nb-scroll-area" style={{maxHeight:height}}>{children}</div>}
export interface TableColumn<T>{key:string;label:string;render:(row:T)=>React.ReactNode;sortValue?:(row:T)=>string|number}
export function DataTable<T>({rows,columns,rowKey,filterText,label='Assets'}:{rows:T[];columns:TableColumn<T>[];rowKey:(r:T)=>string;filterText:(r:T)=>string;label?:string}){const [query,setQuery]=React.useState(''),[selected,setSelected]=React.useState<string[]>([]),[sort,setSort]=React.useState<{key:string;asc:boolean}|null>(null);const visible=rows.filter(r=>filterText(r).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>{const col=columns.find(c=>c.key===sort?.key);if(!sort||!col?.sortValue)return 0;return String(col.sortValue(a)).localeCompare(String(col.sortValue(b)),undefined,{numeric:true})*(sort.asc?1:-1)});return <div className="data-table"><div className="row between table-toolbar"><div className="search-field"><Search size={15}/><Input aria-label={'Filter '+label.toLowerCase()} placeholder={'Filter '+label.toLowerCase()+'…'} value={query} onChange={e=>setQuery(e.target.value)}/></div><span className="muted small">{selected.length} selected</span></div><div className="table-scroll"><table className="nb-table"><caption className="sr-only">{label}</caption><thead><tr><th><input type="checkbox" aria-label={'Select all '+label.toLowerCase()} checked={visible.length>0&&visible.every(r=>selected.includes(rowKey(r)))} onChange={e=>setSelected(e.target.checked?visible.map(rowKey):[])}/></th>{columns.map(c=><th key={c.key} aria-sort={sort?.key===c.key?(sort.asc?'ascending':'descending'):'none'}>{c.sortValue?<button onClick={()=>setSort({key:c.key,asc:sort?.key===c.key?!sort.asc:true})}>{c.label} {sort?.key===c.key?(sort.asc?'↑':'↓'):'↕'}</button>:c.label}</th>)}</tr></thead><tbody>{visible.map(r=><tr key={rowKey(r)} data-selected={selected.includes(rowKey(r))}><td><input type="checkbox" aria-label={'Select '+rowKey(r)} checked={selected.includes(rowKey(r))} onChange={()=>setSelected(a=>a.includes(rowKey(r))?a.filter(x=>x!==rowKey(r)):[...a,rowKey(r)])}/></td>{columns.map(c=><td key={c.key}>{c.render(r)}</td>)}</tr>)}</tbody></table>{!visible.length&&<Empty icon={<Search/>} title="No matching results" description="Try a different search."/>}</div></div>}
export function Sparkline({values,label}:{values:number[];label:string}){const max=Math.max(...values,1),min=Math.min(...values,0);const points=values.map((v,i)=>`${i/Math.max(1,values.length-1)*200},${48-(v-min)/Math.max(1,max-min)*40}`).join(' ');return <svg role="img" aria-label={label} viewBox="0 0 200 55" className="nb-sparkline"><polyline fill="none" stroke="currentColor" strokeWidth="2" points={points}/></svg>}

import * as React from 'react';
import {AnimatePresence,motion} from 'motion/react';
import {Command} from 'cmdk';
import {CheckCircle2,X,ChevronRight} from 'lucide-react';
import {Button,Dialog} from './primitives';
type ToastMessage={id:number;title:string;description?:string};
const ToastContext=React.createContext<((title:string,description?:string)=>void)|null>(null);
export function ToastProvider({children}:{children:React.ReactNode}){const [messages,setMessages]=React.useState<ToastMessage[]>([]);const timers=React.useRef<ReturnType<typeof setTimeout>[]>([]);React.useEffect(()=>()=>timers.current.forEach(clearTimeout),[]);const toast=React.useCallback((title:string,description?:string)=>{const id=Date.now()+Math.random();setMessages(m=>[...m,{id,title,description}]);timers.current.push(setTimeout(()=>setMessages(m=>m.filter(x=>x.id!==id)),4500))},[]);return <ToastContext.Provider value={toast}>{children}<div className="toast-stack" aria-live="polite"><AnimatePresence>{messages.map(m=><motion.div className="nb-toast nb-glass" key={m.id} initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,x:20}}><CheckCircle2 size={18}/><div><strong>{m.title}</strong>{m.description&&<p>{m.description}</p>}</div><Button size="icon" variant="ghost" aria-label="Dismiss notification" onClick={()=>setMessages(a=>a.filter(x=>x.id!==m.id))}><X size={15}/></Button></motion.div>)}</AnimatePresence></div></ToastContext.Provider>}
export function useToast(){const toast=React.useContext(ToastContext);if(!toast)throw new Error('useToast requires ToastProvider');return toast}
export function Sheet(props:React.ComponentProps<typeof Dialog>){return <Dialog {...props} sheet/>}
export function CommandPalette({open,onOpenChange,items}:{open:boolean;onOpenChange:(open:boolean)=>void;items:{id:string;label:string;icon?:React.ReactNode;onSelect:()=>void}[]}){return <Dialog open={open} onOpenChange={onOpenChange} title="Command palette" description="Type to search, use arrows to navigate, and Enter to select."><Command className="nb-command" label="Command palette"><Command.Input placeholder="Search commands…"/><Command.List><Command.Empty>No matching commands.</Command.Empty>{items.map(i=><Command.Item key={i.id} value={i.label} onSelect={()=>{i.onSelect();onOpenChange(false)}}>{i.icon}{i.label}<ChevronRight size={14}/></Command.Item>)}</Command.List></Command></Dialog>}

import * as React from 'react';
import {motion,useReducedMotionConfig} from 'motion/react';
import {Check,ChevronRight,Film,Play,Pause,SkipBack,SkipForward,Volume2,Maximize,ArrowUpRight,Cpu,HardDrive,Clock,Layers,Send,Paperclip,RotateCcw} from 'lucide-react';
import {Button,Badge,Card,Progress,Avatar,Input} from '../ui/primitives';
import {cn} from '../../lib/nbrain-utils';

export function Wordmark({className}: {className?:string}){return <span className={cn('wordmark',className)}>N<span className="apostrophe">’</span>BRAIN</span>}
declare const __NBRAIN_BRAND_URL__: string;
export function BrandIcon({src=(typeof __NBRAIN_BRAND_URL__!=="undefined"?__NBRAIN_BRAND_URL__:"./assets/identity.png")}:{src?:string}={}){return <div className="brand-icon" role="img" aria-label="n’brain metallic brain logo"><img src={src} alt=""/></div>}
export function AgentCore({size='md',active=true}:{size?:'sm'|'md'|'lg';active?:boolean}){return <div className={cn('agent-core','core-'+size,active&&'core-active')} aria-label={active?'N core active':'N core idle'}><span className="core-glyph">N</span><i className="core-ray core-ray-top"/><i className="core-ray core-ray-bottom"/></div>}
export type AgentStatus='idle'|'running'|'ready'|'blocked';
export interface Agent {id:string;name:string;task:string;status:AgentStatus;progress?:number}
export function AgentCard({agent,onSelect}:{agent:Agent;onSelect?:()=>void}){const labels={idle:'Waiting',running:'Rendering',ready:'Ready',blocked:'Needs input'};return <button className={cn('agent-card','agent-'+agent.status)} onClick={onSelect}><span className="agent-icon"><Cpu size={18}/></span><span className="agent-info"><strong>{agent.name}</strong><span>{agent.task}</span>{agent.status==='running'&&<Progress value={agent.progress||0} label={agent.name+' progress'}/>}</span><Badge tone={agent.status==='ready'?'success':agent.status==='blocked'?'warning':agent.status==='running'?'blue':'neutral'}>{labels[agent.status]}</Badge><ChevronRight size={14}/></button>}
export function AgentOrchestrator({agents,onSelect}:{agents:Agent[];onSelect?:(a:Agent)=>void}){const reduced=useReducedMotionConfig();return <div className="orchestrator"><div className="orchestrator-core"><AgentCore size="lg"/></div><svg className="agent-paths" viewBox="0 0 360 130" aria-hidden="true"><defs><linearGradient id="energy-path"><stop stopColor="#6088ff"/><stop offset="1" stopColor="#2634d9"/></linearGradient></defs>{[50,180,310].map((x,i)=><React.Fragment key={x}><path className="energy-rail" d={`M180 0C180 70 ${x} 30 ${x} 125`}/><motion.path className={i===1?'energy-line active':'energy-line'} d={`M180 0C180 70 ${x} 30 ${x} 125`} strokeDasharray="8 18" animate={reduced?undefined:{strokeDashoffset:[0,-52]}} transition={{duration:2.2+i*.3,repeat:Infinity,ease:'linear'}}/></React.Fragment>)}</svg><div className="agent-stack">{agents.map(a=><AgentCard key={a.id} agent={a} onSelect={()=>onSelect?.(a)}/>)}</div></div>}
export function GlassProjectCard({title='Night Drive',onOpen}:{title?:string;onOpen?:()=>void}){return <motion.div whileHover={{y:-4}} transition={{type:'spring',stiffness:250,damping:26}}><Card glass className="glass-project"><div className="glass-card-sheen"/><div className="row between"><span className="eyebrow">PROJECT / 001</span><Badge tone="blue">In production</Badge></div><div className="project-title">{title}</div><p className="muted">Music video · Studio A</p><div className="project-card-meta"><span><Layers size={14}/> 24 shots</span><span><Clock size={14}/> 02:16</span><Avatar initials="JD"/></div><SeparatorLine/><div className="row between"><span className="mono small">V03 · 4K · 24 FPS</span><Button size="sm" variant="silver" onClick={onOpen}>Open project <ArrowUpRight size={14}/></Button></div></Card></motion.div>}
function SeparatorLine(){return <div className="nb-separator"/>}
