export interface NumericScrubProps {label:string;value:number;onValueChange:(value:number)=>void;min?:number;max?:number;step?:number;unit?:string;defaultValue?:number;disabled?:boolean}
export function NumericScrub({label,value,onValueChange,min=-Infinity,max=Infinity,step=1,unit,defaultValue,disabled=false}:NumericScrubProps){
