 const id=React.useId(),cleanup=React.useRef<(()=>void)|null>(null);React.useEffect(()=>()=>cleanup.current?.(),[]);
 const commit=(v:number)=>{if(Number.isFinite(v))onValueChange(Math.max(min,Math.min(max,Math.round(v/step)*step)))};
 const drag=(e:React.PointerEvent<HTMLButtonElement>)=>{if(disabled)return;e.preventDefault();const start=e.clientX,initial=value;const move=(ev:PointerEvent)=>commit(initial+(ev.clientX-start)*step*(ev.shiftKey?.1:1));const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',end);cleanup.current=null};cleanup.current?.();window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true});window.addEventListener('pointercancel',end,{once:true});cleanup.current=end};
 return <div className="nb-numeric"><label htmlFor={id}>{label}</label><div className="nb-numeric-control"><button type="button" className="nb-scrub-grip" aria-label={`Drag to adjust ${label}; Shift for precision`} onPointerDown={drag} onKeyDown={e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();commit(value+(e.key==='ArrowRight'?step:-step))}}} disabled={disabled}><Grip size={11}/></button><input id={id} type="number" value={draft} min={Number.isFinite(min)?min:undefined} max={Number.isFinite(max)?max:undefined} step={step} disabled={disabled} onFocus={()=>{editing.current=true}} onBlur={()=>{editing.current=false;const number=Number(draft);if(draft.trim()&&Number.isFinite(number)){commit(number);setDraft(String(Math.max(min,Math.min(max,Math.round(number/step)*step))))}else setDraft(String(value))}} onChange={e=>{setDraft(e.currentTarget.value);if(Number.isFinite(e.currentTarget.valueAsNumber))commit(e.currentTarget.valueAsNumber)}}/>{unit&&<span>{unit}</span>}{defaultValue!==undefined&&<button type="button" aria-label={`Reset ${label}`} disabled={disabled||value===defaultValue} onClick={()=>onValueChange(defaultValue)}><RotateCcw size={11}/></button>}</div></div>;
}
