import {widgetDefinitions,type WidgetId} from './catalog-data';
export {widgetDefinitions};export type {WidgetId};
export type WidgetPresentation='control'|'parameter'|'tree'|'table'|'queue'|'chat'|'editor'|'graph'|'board'|'engine'|'signal'|'report'|'schedule'|'agent';
const groups:Record<WidgetPresentation,readonly WidgetId[]>={
 control:['button','slider','fader','toggle','number','label','bezier','colorpicker','colorpalette','gel','joystick','modulator','textinput','multiline','filepicker'],
 parameter:['detail','transform','colorgrade','viewportcontrols','camera_switcher'],
 tree:['browser','wiki','list','lore_client'],table:['shotlist','prop_breakdown','compliance','chronometry','production'],
 queue:['renderqueue','actionlog','assimilatelog','version_history','lore_vcs'],chat:['chat','rooms','research'],
 editor:['screenplay','markdown_viewer','charactersheet','locationsheet','elementsheet','visualbible'],
 graph:['pipeline','minipipeline','knowledge_graph','graph'],board:['assetviewer','storyimage','moodwall','corkboard','pitch'],
 engine:['image','three','pascal','supersplat','stage_plan','drawing_canvas','plates','streamdiffusion','timeline','playercontrol','review'],
 signal:['scope','audioanalysis','vumeter'],report:['report','story_report','dashboard'],schedule:['shoot_schedule'],agent:['supervisor','suggestions','gatesheet','h3_composer']
};
export function getWidgetPresentation(id:WidgetId):WidgetPresentation{for(const [kind,ids]of Object.entries(groups))if(ids.includes(id))return kind as WidgetPresentation;throw new Error('Unmapped widget: '+id)}
export const widgetCatalog=widgetDefinitions.map(d=>({...d,presentation:getWidgetPresentation(d.id),implementation:getWidgetPresentation(d.id)==='engine'?'engine-slot' as const:getWidgetPresentation(d.id)==='control'?'control' as const:'composition' as const}));
export function getWidgetDefinition(id:WidgetId){return widgetCatalog.find(d=>d.id===id)!}

import * as React from 'react';
import {motion} from 'motion/react';
import {Play,Pause,Box,FileText,Folder,ChevronRight,Check,RotateCcw,ArrowUpRight,Camera,Send,Plus,Volume2} from 'lucide-react';
import {Button,Input,Textarea,Switch,Slider,Progress,Badge,Checkbox} from '../components/ui/primitives';
import {NumericScrub} from '../components/system/controls';
import {cn} from '../lib/utils';
export interface ScalarWidgetProps {value:number;onValueChange:(value:number)=>void;label?:string;min?:number;max?:number;unit?:string}
export function SliderWidget({value,onValueChange,label='Level',min=0,max=100}:ScalarWidgetProps){return <div className="nb-control-instrument"><span className="nb-instrument-value">{value.toFixed(0)}<small>%</small></span><Slider value={value} min={min} max={max} onValueChange={onValueChange} label={label}/></div>}
export function FaderWidget({value,onValueChange,label='Gain',min=0,max=100}:ScalarWidgetProps){return <div className="nb-fader"><div className="nb-fader-scale"><span>+12</span><span>0</span><span>−12</span><span>−∞</span></div><input type="range" aria-label={label} min={min} max={max} value={value} onChange={e=>onValueChange(+e.target.value)}/><strong>{value}</strong></div>}
export function NumericWidget({value,onValueChange,label='Value',unit=''}:ScalarWidgetProps){return <div className="nb-control-instrument"><NumericScrub label={label} value={value} onValueChange={onValueChange} unit={unit} defaultValue={0}/></div>}
export function ButtonWidget({label='Execute',onExecute,loading=false}:{label?:string;onExecute:()=>void;loading?:boolean}){return <div className="nb-control-instrument"><Button variant="primary" size="lg" loading={loading} onClick={onExecute}><Play size={16}/>{label}</Button><span className="nb-instrument-caption">MANUAL TRIGGER</span></div>}
export function ToggleWidget({value,onValueChange,label='Enabled'}:{value:boolean;onValueChange:(v:boolean)=>void;label?:string}){return <div className="nb-control-instrument"><span className={cn('nb-instrument-indicator',value&&'on')}/><Switch label={label} checked={value} onCheckedChange={onValueChange}/></div>}
export function TextWidget({value,onValueChange,multiline=false,label='Text'}:{value:string;onValueChange:(v:string)=>void;multiline?:boolean;label?:string}){return multiline?<Textarea aria-label={label} value={value} onChange={e=>onValueChange(e.target.value)}/>:<Input aria-label={label} value={value} onChange={e=>onValueChange(e.target.value)}/>}
export function ColorWidget({value,onValueChange,palette}:{value:string;onValueChange:(v:string)=>void;palette?:readonly string[]}){return <div className="nb-color-widget"><label className="nb-color-field" style={{background:value}}><input type="color" aria-label="Choose color" value={value} onChange={e=>onValueChange(e.target.value)}/><span>{value.toUpperCase()}</span></label>{palette&&<div className="nb-palette">{palette.map(c=><button type="button" key={c} style={{background:c}} aria-label={'Choose '+c} aria-pressed={c===value} onClick={()=>onValueChange(c)}/>)}</div>}</div>}
export function JoystickWidget({value,onValueChange}:{value:{x:number;y:number};onValueChange:(v:{x:number;y:number})=>void}){const ref=React.useRef<HTMLDivElement>(null);const point=(e:React.PointerEvent)=>{const r=ref.current!.getBoundingClientRect();onValueChange({x:Math.max(-1,Math.min(1,(e.clientX-r.left)/r.width*2-1)),y:Math.max(-1,Math.min(1,(e.clientY-r.top)/r.height*2-1))})};return <div className="nb-joystick-wrap"><div ref={ref} className="nb-joystick" tabIndex={0} role="group" aria-label="Joystick. Arrow keys adjust pan and tilt" onKeyDown={e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();onValueChange({x:Math.max(-1,Math.min(1,value.x+(e.key==='ArrowRight'?.1:e.key==='ArrowLeft'?-.1:0))),y:Math.max(-1,Math.min(1,value.y+(e.key==='ArrowDown'?.1:e.key==='ArrowUp'?-.1:0)))})}} onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId);point(e)}} onPointerMove={e=>{if(e.currentTarget.hasPointerCapture(e.pointerId))point(e)}}><i className="nb-joystick-cross"/><motion.span animate={{left:`${(value.x+1)*50}%`,top:`${(value.y+1)*50}%`}} transition={{duration:.08}}/></div><div className="nb-axis-readout"><span>X {value.x.toFixed(2)}</span><span>Y {value.y.toFixed(2)}</span><Button size="sm" variant="ghost" onClick={()=>onValueChange({x:0,y:0})}>Center</Button></div></div>}
export function CurveWidget({value,onValueChange}:ScalarWidgetProps){const c=Math.max(0,Math.min(100,value));return <div className="nb-curve-widget"><svg viewBox="0 0 300 160" role="img" aria-label="Easing curve"><path className="nb-chart-grid" d="M10 10H290M10 80H290M10 150H290M10 10V150M150 10V150M290 10V150"/><path className="nb-chart-line" d={`M10 150C${10+c*2.8} 150 ${290-c*2.8} 10 290 10`}/><circle cx={10+c*2.8} cy="150" r="4"/><circle cx={290-c*2.8} cy="10" r="4"/></svg><Slider label="Curve tension" value={c} onValueChange={onValueChange}/></div>}
export function ScopeWidget({samples,label='Signal'}:{samples:readonly number[];label?:string}){const points=samples.map((s,i)=>`${i*300/Math.max(1,samples.length-1)},${80-Math.max(-1,Math.min(1,s))*65}`).join(' ');return <div className="nb-scope"><svg viewBox="0 0 300 160" role="img" aria-label={label}><path className="nb-chart-grid" d="M0 15H300M0 80H300M0 145H300M75 0V160M150 0V160M225 0V160"/><polyline className="nb-chart-line" points={points}/></svg><span className="nb-instrument-caption">{label}</span></div>}
export interface WidgetItem {id:string;label:string;detail?:string;status?:'ready'|'running'|'blocked'|'queued';progress?:number;children?:readonly WidgetItem[];color?:string}
export function AssetGridWidget({items,selectedId,onSelect}:{items:readonly WidgetItem[];selectedId?:string;onSelect?:(id:string)=>void}){return <div className="nb-asset-grid">{items.map((x,i)=><button type="button" key={x.id} className={cn('nb-asset-tile',selectedId===x.id&&'selected')} onClick={()=>onSelect?.(x.id)} aria-pressed={selectedId===x.id}><div className={'nb-asset-art nb-art-'+i%4} style={x.color?{background:x.color}:undefined}><Box size={26}/></div><strong>{x.label}</strong><span>{x.detail}</span></button>)}</div>}
export function TreeWidget({items,onSelect,selectedId}:{items:readonly WidgetItem[];onSelect?:(id:string)=>void;selectedId?:string}){const [expanded,setExpanded]=React.useState<string[]>(()=>items.filter(x=>x.children).map(x=>x.id));const rows=(list:readonly WidgetItem[],depth=0):React.ReactNode=>list.map(x=><React.Fragment key={x.id}><div className={cn('nb-tree-row',selectedId===x.id&&'selected')} style={{paddingLeft:8+depth*17}}>{x.children?<button aria-label={(expanded.includes(x.id)?'Collapse ':'Expand ')+x.label} aria-expanded={expanded.includes(x.id)} onClick={()=>setExpanded(v=>v.includes(x.id)?v.filter(i=>i!==x.id):[...v,x.id])}><ChevronRight size={12} style={{rotate:expanded.includes(x.id)?'90deg':'0deg'}}/></button>:<span className="nb-tree-spacer"/>}<button onClick={()=>onSelect?.(x.id)}><Folder size={13}/>{x.label}<small>{x.detail}</small></button></div>{x.children&&expanded.includes(x.id)&&rows(x.children,depth+1)}</React.Fragment>);return <div className="nb-tree">{rows(items)}</div>}
export function QueueWidget({items,onAction}:{items:readonly WidgetItem[];onAction?:(action:string,id?:string)=>void}){return <div className="nb-queue">{items.map(x=><div className="nb-queue-row" key={x.id}><span className="nb-queue-thumbnail"><Box size={18}/></span><div><strong>{x.label}</strong><small>{x.detail}</small>{x.status==='running'&&<Progress value={x.progress??0} label={x.label+' progress'}/>}</div><Badge tone={x.status==='running'?'blue':x.status==='blocked'?'warning':x.status==='ready'?'success':'neutral'}>{x.status||'queued'}</Badge>{onAction&&<Button size="icon" variant="ghost" aria-label={'Inspect '+x.label} onClick={()=>onAction('inspect',x.id)}><ArrowUpRight size={12}/></Button>}</div>)}</div>}
export interface WidgetMessage {id:string;role:'human'|'agent';name:string;text:string}
export function ChatWidget({messages,onSend}:{messages:readonly WidgetMessage[];onSend?:(text:string)=>void}){const [text,setText]=React.useState('');const send=()=>{if(!text.trim())return;onSend?.(text.trim());setText('')};return <div className="nb-chat-widget"><div role="log" className="nb-chat-messages">{messages.map(x=><div key={x.id} className={'nb-chat-message nb-chat-'+x.role}><span>{x.name} / {x.role}</span><p>{x.text}</p></div>)}</div><form onSubmit={e=>{e.preventDefault();send()}}><Input aria-label="Message" value={text} onChange={e=>setText(e.target.value)} placeholder="Ask your team or agent…"/><Button size="icon" type="submit" aria-label="Send message" disabled={!text.trim()}><Send size={14}/></Button></form></div>}
export function EngineViewport({children,label='Viewport',toolbar,footer}:{children?:React.ReactNode;label?:string;toolbar?:React.ReactNode;footer?:React.ReactNode}){return <div className="nb-engine-viewport"><div className="nb-viewport-toolbar">{toolbar}</div><div className="nb-engine-content" aria-label={label}>{children??<div className="nb-engine-slot"><Box size={28}/><span>Connect your {label.toLowerCase()} renderer</span></div>}</div>{footer&&<div className="nb-viewport-footer">{footer}</div>}</div>}
export function MeterWidget({value,onValueChange}:ScalarWidgetProps){return <div className="nb-meter-widget"><div className="nb-meter-bars">{[0,1].map(i=><div key={i} role="meter" aria-label={i?'Right audio level':'Left audio level'} aria-valuenow={Math.max(0,value-i*7)} aria-valuemin={0} aria-valuemax={100}>{Array.from({length:24},(_,n)=><i key={n} className={value-i*7>n/24*100?'lit':''} style={{background:n>20?'#ce727a':n>17?'#bfa46b':'#6385ed'}}/>)}</div>)}</div><Slider label="Monitor level" value={value} onValueChange={onValueChange}/></div>}
export function TransformWidget({value,onValueChange}:{value:{x:number;y:number;z:number};onValueChange:(value:{x:number;y:number;z:number})=>void}){return <div className="nb-transform-widget">{(['x','y','z'] as const).map(axis=><NumericScrub key={axis} label={axis.toUpperCase()} unit="m" value={value[axis]} onValueChange={n=>onValueChange({...value,[axis]:n})} step={.1} defaultValue={0}/>)}</div>}

import * as React from 'react';
import {Film,Check,Plus,Play,Pause,FileText,GitBranch,ArrowUpRight,Volume2} from 'lucide-react';
import {Button,Input,Textarea,Switch,Slider,Badge,Progress,FileUpload} from '../components/nbrain';
import {ParameterRow,NumericScrub} from '../components/system/controls';
import {AgentCore} from '../components/nbrain/production';
import {getWidgetDefinition,type WidgetId} from './catalog';
import * as W from './views';
export interface WidgetValue {scalar:number;text:string;enabled:boolean;color:string;point:{x:number;y:number};transform:{x:number;y:number;z:number};playing:boolean;selectedId?:string}
export const defaultWidgetValue:WidgetValue={scalar:62,text:'',enabled:true,color:'#4167e9',point:{x:0,y:0},transform:{x:0,y:0,z:0},playing:false};
export interface WidgetViewProps {widgetId:WidgetId;value:WidgetValue;onValueChange:(value:WidgetValue)=>void;items?:readonly W.WidgetItem[];messages?:readonly W.WidgetMessage[];samples?:readonly number[];onAction?:(action:string,id?:string)=>void;children?:React.ReactNode;description?:string}
/** Controlled presentation layer. The host retains data, execution and specialized engines. */
export function WidgetView({widgetId:id,value:v,onValueChange,items=[],messages=[],samples=[],onAction,children,description}:WidgetViewProps){const d=getWidgetDefinition(id);const set=<K extends keyof WidgetValue>(key:K,value:WidgetValue[K])=>onValueChange({...v,[key]:value});const scalar={value:v.scalar,onValueChange:(n:number)=>set('scalar',n)};
 switch(id){
 case 'button':return <W.ButtonWidget label={v.text||d.label} onExecute={()=>onAction?.('execute')}/>;
 case 'toggle':return <W.ToggleWidget value={v.enabled} onValueChange={b=>set('enabled',b)}/>;
 case 'slider':return <W.SliderWidget {...scalar}/>;
 case 'fader':return <W.FaderWidget {...scalar}/>;
 case 'number':return <W.NumericWidget {...scalar} label="Value"/>;
 case 'label':return <div className="nb-control-instrument"><span className="nb-instrument-value nb-label-display">{v.text||'—'}</span><span className="nb-instrument-caption">{description}</span></div>;
 case 'bezier':return <W.CurveWidget {...scalar}/>;
 case 'joystick':return <W.JoystickWidget value={v.point} onValueChange={p=>set('point',p)}/>;
 case 'textinput':case 'multiline':return <W.TextWidget value={v.text} onValueChange={s=>set('text',s)} multiline={id==='multiline'} label={d.label}/>;
 case 'colorpicker':case 'colorpalette':case 'gel':return <W.ColorWidget value={v.color} onValueChange={c=>set('color',c)} palette={items.map(i=>i.color!).filter(Boolean)}/>;
 case 'filepicker':return <FileUpload label="Choose a local file" onFile={f=>{set('text',f.name);onAction?.('files-selected')}}/>;
 case 'modulator':return <div className="nb-widget-stack"><W.ScopeWidget samples={samples} label="LFO / Sine"/><W.SliderWidget {...scalar} label="Frequency"/></div>;
 case 'transform':return <W.TransformWidget value={v.transform} onValueChange={t=>set('transform',t)}/>;
 case 'scope':case 'graph':case 'audioanalysis':return <W.ScopeWidget samples={samples} label={id==='audioanalysis'?'Spectral envelope':d.label}/>;
 case 'vumeter':return <W.MeterWidget {...scalar}/>;
 }
 switch(d.presentation){
 case 'parameter':return <div className="nb-widget-stack"><ParameterRow label={id==='camera_switcher'?'Active camera':'Exposure'} hint={id==='colorgrade'?'Scene referred':'Local override'} changed={v.scalar!==50} onReset={()=>set('scalar',50)}><NumericScrub label="Value" {...scalar} step={.1}/></ParameterRow><Slider label={id==='colorgrade'?'Contrast':'Intensity'} {...scalar}/><Switch label={id==='camera_switcher'?'Follow preview':'Auto update'} checked={v.enabled} onCheckedChange={b=>set('enabled',b)}/>{items.map(x=><Button key={x.id} variant={v.selectedId===x.id?'primary':'secondary'} aria-pressed={v.selectedId===x.id} onClick={()=>set('selectedId',x.id)}>{x.label}</Button>)}</div>;
 case 'tree':return <div className="nb-widget-stack"><Input aria-label={'Search '+d.label} placeholder="Filter…" value={v.text} onChange={e=>set('text',e.target.value)}/><W.TreeWidget items={items.filter(i=>!v.text||i.label.toLowerCase().includes(v.text.toLowerCase())||i.children?.some(c=>c.label.toLowerCase().includes(v.text.toLowerCase())))} selectedId={v.selectedId} onSelect={s=>set('selectedId',s)}/></div>;
 case 'table':return <div className="nb-widget-table-wrap"><table className="nb-widget-table"><thead><tr><th>Name</th><th>Details</th><th>Status</th></tr></thead><tbody>{items.map(x=><tr key={x.id} onClick={()=>set('selectedId',x.id)} aria-selected={v.selectedId===x.id}><td><button onClick={()=>set('selectedId',x.id)}>{x.label}</button></td><td>{x.detail}</td><td><Badge tone={x.status==='blocked'?'warning':x.status==='ready'?'success':'neutral'}>{x.status||'draft'}</Badge></td></tr>)}</tbody></table></div>;
 case 'queue':return <W.QueueWidget items={items} onAction={onAction}/>;
 case 'chat':return <W.ChatWidget messages={messages} onSend={text=>onAction?.('send-message',text)}/>;
 case 'editor':return <div className="nb-widget-editor"><div className="nb-editor-toolbar"><Badge>LOCAL DRAFT</Badge><Button size="sm" variant="ghost" onClick={()=>onAction?.('save')}>Save draft</Button></div><Textarea aria-label={d.label} value={v.text} onChange={e=>set('text',e.target.value)}/>{description&&<p>{description}</p>}</div>;
 case 'board':return <W.AssetGridWidget items={items} selectedId={v.selectedId} onSelect={s=>set('selectedId',s)}/>;
 case 'graph':return <div className="nb-node-graph"><svg viewBox="0 0 500 140" aria-hidden="true"><path d="M100 70H400"/></svg>{items.map((x,i)=><button key={x.id} onClick={()=>{set('selectedId',x.id);onAction?.('inspect',x.id)}} className={v.selectedId===x.id?'selected':''}><GitBranch size={18}/><strong>{x.label}</strong><span>{x.detail}</span><i>{String(i+1).padStart(2,'0')}</i></button>)}</div>;
 case 'engine':return <W.EngineViewport label={d.label} toolbar={<><Badge>LOCAL</Badge><span className="nb-viewport-label">{d.label}</span><Button variant="ghost" size="sm" onClick={()=>onAction?.('fit')}>Fit</Button></>} footer={<><Button variant="ghost" size="icon" aria-label={v.playing?'Pause':'Play'} onClick={()=>set('playing',!v.playing)}>{v.playing?<Pause size={14}/>:<Play size={14}/>}</Button><span>00:00:{String(Math.round(v.scalar)).padStart(2,'0')}</span><input type="range" aria-label="Position" value={v.scalar} onChange={e=>set('scalar',+e.target.value)}/><Volume2 size={13}/></>}>{children}</W.EngineViewport>;
 case 'schedule':return <div className="nb-schedule"><div className="nb-schedule-ruler"><span>08:00</span><span>10:00</span><span>12:00</span><span>14:00</span></div>{items.map((x,i)=><div className="nb-schedule-row" key={x.id}><span>{x.label}</span><button style={{marginLeft:`${i*7}%`,width:`${35+i*4}%`}} onClick={()=>onAction?.('inspect',x.id)}>{x.detail}</button></div>)}</div>;
 case 'report':return <div className="nb-report-widget"><div className="nb-report-metrics">{items.slice(0,3).map(x=><div key={x.id}><span>{x.label}</span><strong>{x.detail}</strong></div>)}</div><W.ScopeWidget samples={samples} label="Project activity"/><Button size="sm" onClick={()=>onAction?.('export')}>Export report</Button></div>;
 case 'agent':return <div className="nb-agent-run"><div className="nb-agent-run-header"><AgentCore size="sm"/><div><strong>{d.label}</strong><span>{description||'Human decisions remain in your control.'}</span></div></div><W.QueueWidget items={items} onAction={onAction}/><div className="nb-agent-decision"><Badge tone="warning">Human approval</Badge><p>Review the proposed next step before execution.</p><Button variant="primary" onClick={()=>onAction?.('approve')}>Approve next stage</Button><Button onClick={()=>onAction?.('revise')}>Request changes</Button></div></div>;
 default:return <div className="nb-widget-stack">{items.map(x=><div key={x.id}>{x.label}</div>)}</div>;
 }
}

import {clsx,type ClassValue} from 'clsx';
